package com.vandorlabs.neoforge.builders;
import com.vandorlabs.neoforge.rack.NativeBatteryModule;import net.minecraft.nbt.*;import net.minecraft.world.item.ItemStack;import net.neoforged.neoforge.energy.IEnergyStorage;
public final class NativeSynthesisRuntime {
 public static final int COST=8000,RATE=40;
 private final NativeBuilderEntity owner;private int selected,building,work,received,worked;private boolean active,connected;private long last=Long.MIN_VALUE;
 NativeSynthesisRuntime(NativeBuilderEntity owner){this.owner=owner;}
 public int selected(){return selected;}public int building(){return active||!owner.getItem(1).isEmpty()?building:selected;}public float progress(){return active?work/(float)COST:owner.getItem(1).isEmpty()?0:1;}public boolean active(){return active;}public boolean connected(){return connected;}
 public void select(int index){if(index<0||index>2)return;selected=index;owner.changed();}
 public static ItemStack result(int index){return new ItemStack(NativeBuilderBindings.CORES.get(NativeBuilderDesigns.at(index).id()));}
 private void budget(){long now=owner.getLevel().getGameTime();if(now!=last){last=now;received=worked=0;}}
 private boolean queued(){return !active&&owner.getItem(1).isEmpty()&&owner.canPlaceItem(0,owner.getItem(0));}
 private void start(){if(owner.enabled()&&queued()){building=selected;owner.owned(0).shrink(1);active=true;work=0;owner.changed();}}
 private void finish(){if(active&&work==COST&&owner.getItem(1).isEmpty()){owner.own(1,result(building));active=false;work=0;owner.changed();}}
 private int receive(int amount,boolean simulate){if(!owner.available()||!owner.formed()||!owner.synthesis())return 0;budget();if(!simulate)start();int available=Math.max(0,Math.min(amount,RATE-received));int recipe=owner.enabled()&&(active||simulate&&queued())&&owner.getItem(1).isEmpty()?Math.min(Math.min(available,RATE-worked),COST-work):0;int charge=NativeBatteryModule.transfer(owner.owned(2),available-recipe,true,true);if(!simulate){received+=recipe+charge;worked+=recipe;work+=recipe;NativeBatteryModule.transfer(owner.owned(2),charge,false,true);if(recipe+charge>0)owner.changed();finish();}return recipe+charge;}
 public final IEnergyStorage energy=new IEnergyStorage(){public int receiveEnergy(int amount,boolean simulate){return receive(amount,simulate);}public int extractEnergy(int amount,boolean simulate){return 0;}public int getEnergyStored(){return work+owner.batteryEnergy();}public int getMaxEnergyStored(){return COST+owner.batteryCapacity();}public boolean canReceive(){return true;}public boolean canExtract(){return false;}};
 public void tick(){if(!owner.available()||!owner.synthesis()||!owner.formed())return;budget();start();if(active&&owner.enabled()&&owner.getItem(1).isEmpty()){int used=NativeBatteryModule.transfer(owner.owned(2),Math.min(RATE-worked,COST-work),false,false);worked+=used;work+=used;if(used>0)owner.changed();finish();}if(owner.getLevel().getGameTime()%20==0){boolean next=false;for(var side:new net.minecraft.core.Direction[]{owner.facing().getOpposite(),net.minecraft.core.Direction.DOWN}){var pos=owner.powerPort().relative(side);if(!NativeBuilderFormation.loaded(owner.getLevel(),pos))continue;var cap=owner.getLevel().getCapability(net.neoforged.neoforge.capabilities.Capabilities.EnergyStorage.BLOCK,pos,side.getOpposite());next|=cap!=null&&cap.canExtract();}if(next!=connected){connected=next;owner.changed();}}}
 public void save(CompoundTag tag){tag.putInt("Selected",selected);tag.putInt("Building",building);tag.putInt("Work",work);tag.putBoolean("Active",active);tag.putBoolean("Connected",connected);}
 public void read(CompoundTag tag){if(!tag.getAllKeys().stream().allMatch(k->java.util.Set.of("Selected","Building","Work","Active","Connected").contains(k)))throw new IllegalArgumentException("Future builder work snapshot");for(var k:java.util.List.of("Selected","Building","Work"))if(tag.contains(k)&&!tag.contains(k,Tag.TAG_INT))throw new IllegalArgumentException("Builder work integer type");for(var k:java.util.List.of("Active","Connected"))if(tag.contains(k)&&(!tag.contains(k,Tag.TAG_BYTE)||tag.getByte(k)<0||tag.getByte(k)>1))throw new IllegalArgumentException("Builder work boolean type");int nextSelected=tag.getInt("Selected"),nextBuilding=tag.getInt("Building"),nextWork=tag.getInt("Work");boolean nextActive=tag.getBoolean("Active");if(nextSelected<0||nextSelected>2||nextBuilding<0||nextBuilding>2||nextWork<0||nextWork>COST||!nextActive&&nextWork!=0)throw new IllegalArgumentException("Builder work snapshot");selected=nextSelected;building=nextBuilding;work=nextWork;active=nextActive;connected=tag.getBoolean("Connected");}

}
